// ─────────────────────────────────────────────
// VHSYS :: nf_service_info
// Rota   : POST /nf_service_info
// ─────────────────────────────────────────────
// Aceita múltiplos formatos de entrada:
// 1) body: { xml_ref: '<xml...>' }
// 2) body: '{"xml_ref":"<xml...>"}'
// 3) body: '<xml...>'
// 4) xml_ref direto no root
// ─────────────────────────────────────────────

const input = $input.first().json || {};

function tryParseJsonString(raw) {
  if (typeof raw !== 'string') return null;
  const s = raw.trim();
  if (!s || (!s.startsWith('{') && !s.startsWith('['))) return null;
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
}

function firstNonEmpty(values) {
  for (const v of values) {
    if (v === null || v === undefined) continue;
    const s = String(v).trim();
    if (s) return s;
  }
  return '';
}

const rawBody = (input.body !== undefined) ? input.body : input;
const parsedBody = tryParseJsonString(rawBody);
const bodyObj = (parsedBody && typeof parsedBody === 'object')
  ? parsedBody
  : (rawBody && typeof rawBody === 'object' ? rawBody : null);

const xml_string = firstNonEmpty([
  bodyObj?.xml_ref,
  input.xml_ref,
  // fallback: quando body já vem como XML puro
  (typeof rawBody === 'string' && rawBody.includes('<xjx')) ? rawBody : '',
  (typeof rawBody === 'string' && rawBody.includes('<?xml')) ? rawBody : ''
]);

if (!xml_string) {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    route: 'nf_service_info',
    event: 'validation_failed',
    body_type: typeof rawBody,
    has_body: rawBody !== undefined && rawBody !== null,
    has_body_xml_ref: Boolean(bodyObj && bodyObj.xml_ref),
    has_root_xml_ref: Boolean(input.xml_ref),
    level: 'warn'
  }));

  return {
    _valid: false,
    statusCode: 400,
    body: { ok: false, error: 'No XML data provided' }
  };
}

console.log(JSON.stringify({
  timestamp: new Date().toISOString(),
  route: 'nf_service_info',
  event: 'input_validated',
  xml_length: xml_string.length,
  level: 'info'
}));

return { _valid: true, xml_string };

// ─────────────────────────────────────────────
// Parse XML + Transform
// ─────────────────────────────────────────────
// Espelha exatamente get_nf_service_info() do Flask:
//   xmltodict.parse → xml_dict['xjx']['cmd']
//   @t = nome do campo, #text = valor
//   clean_cell() em cada valor
//   del 'no-set', 'estoque_pedido', 'bloquear_edicao_cliente'
// ─────────────────────────────────────────────

const ctx = $input.first().json;
const xml_string = ctx.xml_string;

const isEmptyListPayload = /Nenhum registro para exibir/i.test(xml_string || '');
if (isEmptyListPayload) {
  return [{ json: { _skip: true, message: 'Empty list payload' } }];
}

// ── clean_cell() — espelha Flask ──
function cleanCell(value) {
  if (typeof value !== 'string') return value;
  let cleaned = value.replace(/\\n|\\t|\\r|\n|\t|\r/g, ' ');
  cleaned = cleaned.replace(/\s+/g, ' ').trim();
  return cleaned;
}

function normalizeNumeric(value) {
  if (value === null || value === undefined) return null;
  let s = String(value).trim();
  if (!s) return null;

  // Se vier no formato pt-BR (1.234,56), converte para formato SQL (1234.56)
  if (s.includes(',')) {
    s = s.replace(/\./g, '').replace(',', '.');
  }

  return s;
}

// ── Parse XML (equivale a xmltodict.parse) ──
// Extrai cada <cmd ... t="campo" ...>valor</cmd>
function parseXjxXml(xml) {
  const info = {};
  const cmdRegex = /<cmd[^>]+t="([^"]*?)"[^>]*>([\s\S]*?)<\/cmd>/g;
  let match;
  while ((match = cmdRegex.exec(xml)) !== null) {
    const fieldName = match[1];
    let value = match[2].replace(/<\!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim();
    info[fieldName] = cleanCell(value);
  }
  return info;
}

let info_dict_ref;
try {
  info_dict_ref = parseXjxXml(xml_string);
} catch (e) {
  return [{ json: { _skip: true, message: 'Failed to parse XML: ' + String(e.message) } }];
}

// Espelha: del info_dict_ref['no-set'] / 'estoque_pedido' / 'bloquear_edicao_cliente'
delete info_dict_ref['no-set'];
delete info_dict_ref['estoque_pedido'];
delete info_dict_ref['bloquear_edicao_cliente'];

// id_servico é a PK — vem do XML
const id_servico = String(info_dict_ref.id_servico || '').trim();
if (!id_servico) {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    route: 'nf_service_info',
    event: 'missing_id_servico',
    available_keys: Object.keys(info_dict_ref),
    level: 'warn'
  }));
  return [{ json: { _skip: true, message: 'Missing id_servico in XML' } }];
}

console.log(JSON.stringify({
  timestamp: new Date().toISOString(),
  route: 'nf_service_info',
  event: 'xml_parsed',
  id_servico,
  fields_count: Object.keys(info_dict_ref).length,
  level: 'info'
}));

return [{
  json: {
    id_servico,
    obs_interno_pedido:          info_dict_ref.obs_interno_pedido          ?? null,
    obs_pedido:                  info_dict_ref.obs_pedido                  ?? null,
    numero_processo:             info_dict_ref.numero_processo             ?? null,
    condicao_pagamento:          info_dict_ref.condicao_pagamento          ?? null,
    condicao_pagamento_id:       info_dict_ref.condicao_pagamento_id       ?? null,
    valor_iss:                   normalizeNumeric(info_dict_ref.valor_iss),
    aliq_iss:                    normalizeNumeric(info_dict_ref.aliq_iss),
    valor_ir:                    normalizeNumeric(info_dict_ref.valor_ir),
    aliq_ir:                     normalizeNumeric(info_dict_ref.aliq_ir),
    valor_contribuicao:          normalizeNumeric(info_dict_ref.valor_contribuicao),
    aliq_contribuicao:           normalizeNumeric(info_dict_ref.aliq_contribuicao),
    valor_pis:                   normalizeNumeric(info_dict_ref.valor_pis),
    aliq_pis:                    normalizeNumeric(info_dict_ref.aliq_pis),
    valor_cofins:                normalizeNumeric(info_dict_ref.valor_cofins),
    aliq_cofins:                 normalizeNumeric(info_dict_ref.aliq_cofins),
    valor_material:              normalizeNumeric(info_dict_ref.valor_material),
    valor_tributos_mun:          normalizeNumeric(info_dict_ref.valor_tributos_mun),
    valor_aliq_tributos_mun:     normalizeNumeric(info_dict_ref.valor_aliq_tributos_mun),
    valor_tributos:              normalizeNumeric(info_dict_ref.valor_tributos),
    valor_aliq_tributos:         normalizeNumeric(info_dict_ref.valor_aliq_tributos),
    valor_imposto:               normalizeNumeric(info_dict_ref.valor_imposto),
    valor_aliquota:              normalizeNumeric(info_dict_ref.valor_aliquota),
    valor_base_calculo:          normalizeNumeric(info_dict_ref.valor_base_calculo),
    valor_condicionado:          normalizeNumeric(info_dict_ref.valor_condicionado),
    valor_incondicionado:        normalizeNumeric(info_dict_ref.valor_incondicionado),
    valor_deducoes:              normalizeNumeric(info_dict_ref.valor_deducoes),
    itemLista_servico:           info_dict_ref.itemLista_servico           ?? null,
    valor_total_nota:            normalizeNumeric(info_dict_ref.valor_total_nota),
    valor_total_servicos:        normalizeNumeric(info_dict_ref.valor_total_servicos),
    desc_servicos:               info_dict_ref.desc_servicos               ?? null,
    serie_nota:                  info_dict_ref.serie_nota                  ?? null,
    id_pedido:                   info_dict_ref.id_pedido                   ?? null,
    vendedor_pedido_id:          info_dict_ref.vendedor_pedido_id          ?? null,
    vendedor_pedido:             info_dict_ref.vendedor_pedido             ?? null,
    ultrapassar_limite_credito:  info_dict_ref.ultrapassar_limite_credito  ?? null,
    contas_pedido:               info_dict_ref.contas_pedido               ?? null,
    id_cliente:                  info_dict_ref.id_cliente                  ?? null,
    nome_cliente:                info_dict_ref.nome_cliente                ?? null
  }
}];

// ── Sucesso ──
// Flask retorna HTTP 200 (não 201)
const row = $input.first().json;
console.log(JSON.stringify({
  timestamp: new Date().toISOString(),
  route: 'nf_service_info',
  event: 'upsert_complete',
  id_servico: row.id_servico,
  level: 'info'
}));
return {
  statusCode: 200,
  body: { message: 'Data extracted, cleaned, and converted to DataFrame successfully' }
};

// ── Erro de validação (sem xml_ref) ──
const input = $input.first().json;
return {
  statusCode: input.statusCode || 400,
  body: input.body || { ok: false, error: 'Validation failed' }
};

// ── Erro de banco durante o UPSERT ──
const errData = $input.first().json;
console.log(JSON.stringify({
  timestamp: new Date().toISOString(),
  route: 'nf_service_info',
  event: 'db_error',
  message: errData.message || 'Unknown DB error',
  level: 'error'
}));
return {
  statusCode: 500,
  body: { ok: false, error: 'Database error', message: 'Could not update service info' }
};
